function StatCard({ icon: Icon, label, value, note, accent = "blue" }: { icon: typeof Activity; label: string; value: string; note: string; accent?: string }) {
  return <Card className="stat-card">
    <div className={`stat-icon ${accent}`}><Icon size={17} strokeWidth={1.8} /></div>
    <div className="stat-copy"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>
  </Card>;
}

function Pill({ children, tone = "slate" }: { children: React.ReactNode; tone?: string }) {
  return <Badge variant="secondary" className={`pill ${tone}`}><span className="pill-dot" />{children}</Badge>;
}

type CommandItem = { key: string; label: string; icon: typeof Activity };
function CommandPalette({ items, onSelect, onClose }: { items: CommandItem[]; onSelect: (key: string) => void; onClose: () => void }) { return <div className="command-backdrop" onClick={onClose}><div className="command-palette" onClick={(event) => event.stopPropagation()}><div className="command-search"><Search size={16} /><input autoFocus placeholder="ابحث عن صفحة أو إجراء..." /></div><div className="command-list">{items.map((item) => <button key={item.key} onClick={() => onSelect(item.key)}><item.icon size={16} /><span>{item.label}</span><ArrowUpRight size={14} /></button>)}<button onClick={() => onSelect("settings")}><Settings2 size={16} /><span>الإعدادات</span><ArrowUpRight size={14} /></button></div><div className="command-hint"><kbd>Esc</kbd> للإغلاق</div></div></div>; }

function AppShell({ active, setActive, children, userName, logout }: { active: PageKey; setActive: (key: PageKey) => void; children: React.ReactNode; userName: string; logout: () => void }) {
  const { theme, toggleTheme } = useTheme();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  useEffect(() => { const handleKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") { setCommandOpen(false); setUserMenuOpen(false); } }; window.addEventListener("keydown", handleKey); return () => window.removeEventListener("keydown", handleKey); }, []);
  const commandItems: CommandItem[] = navGroups.flatMap((group) => group.items.map((item) => ({ key: String(item.key), label: item.label, icon: item.icon as typeof Activity })));
  return <div className="app-shell" dir="rtl">
    <aside className={`sidebar ${mobileOpen ? "mobile-open" : ""}`}>
      <div className="brand-row">
        <div className="brand-mark"><img src="/manus-storage/venture-os-mark_cc2bdbe7.png" alt="" /></div>
        <div><strong>Venture OS</strong><span>مختبرك الشخصي</span></div>
        <button className="icon-button sidebar-close" onClick={() => setMobileOpen(false)}><X size={17} /></button>
      </div>
      <nav className="side-nav">
        {navGroups.map((group) => <div className="nav-group" key={group.label}><span className="nav-label">{group.label}</span>{group.items.map((item) => <button key={item.key} className={`nav-item ${active === item.key ? "active" : ""}`} onClick={() => { setActive(item.key as PageKey); setMobileOpen(false); }}><item.icon size={17} strokeWidth={active === item.key ? 2.1 : 1.7} /><span>{item.label}</span>{item.key === "tasks" && <b className="nav-count">3</b>}</button>)}</div>)}
      </nav>
      <div className="sidebar-bottom"><div className="sidebar-status"><span className="live-dot" /><div><strong>المساعد متصل</strong><span>آخر مزامنة منذ 3 د</span></div></div></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><button className="mobile-menu icon-button" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div className="breadcrumbs"><span>Venture OS</span><span>/</span><strong>{pageMeta[active].title}</strong></div><div className="top-actions"><button className="search-trigger" onClick={() => setCommandOpen(true)}><Search size={16} /><span>ابحث وتنقل في مساحتك</span><kbd>⌘ K</kbd></button><button className="icon-button" onClick={() => toast("لا توجد تنبيهات جديدة") }><Bell size={18} /><i className="notification-dot" /></button><button className="icon-button" onClick={toggleTheme}>{theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}</button><div className="user-menu-wrap"><button className="user-trigger" onClick={() => setUserMenuOpen((open) => !open)} aria-expanded={userMenuOpen}><span className="top-avatar">{userName.slice(0, 1)}</span><span className="user-trigger-name">{userName}</span><ChevronDown size={14} /></button>{userMenuOpen && <div className="user-menu"><div className="user-menu-heading"><span className="top-avatar">{userName.slice(0, 1)}</span><div><strong>{userName}</strong><small>مساحة شخصية</small></div></div><button onClick={() => { setActive("settings"); setUserMenuOpen(false); }}><Settings2 size={15} /> الإعدادات</button><button onClick={() => { setUserMenuOpen(false); logout(); }}><LogOut size={15} /> تسجيل الخروج</button></div>}</div></div></header>
      <div className="page-content">{children}</div>
    {commandOpen && <CommandPalette items={commandItems} onSelect={(key) => { setActive(key as PageKey); setCommandOpen(false); }} onClose={() => setCommandOpen(false)} />}
    </main>
  </div>;
}

function DashboardCharts() { const { isAuthenticated } = useAuth(); const githubQuery = trpc.github.status.useQuery(undefined, { enabled: isAuthenticated, retry: false }); const [range, setRange] = useState("7d"); const github = githubQuery.data?.connected ? githubQuery.data : null; const progressData = github ? [{ name: github.repo.split("/").pop() ?? "GitHub", value: github.health }, ...projectProgressData.slice(0, 3)] : projectProgressData; const marketData = github ? marketSignalData.map((item, index) => index === marketSignalData.length - 1 ? { ...item, signals: Math.max(item.signals, github.recentCommits), opportunities: Math.max(item.opportunities, Math.min(github.openIssues, 9)) } : item) : marketSignalData; return <section className="charts-grid"><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Project pulse</p><h2>تقدم المشاريع</h2><span className="chart-note">{github ? "تتضمن حالة مستودع GitHub المرتبط" : "نسبة الإنجاز الحالية لكل مشروع"}</span></div><select value={range} onChange={(e) => setRange(e.target.value)} aria-label="فترة الرسم"><option value="7d">هذا الأسبوع</option><option value="30d">هذا الشهر</option></select></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={progressData} layout="vertical" margin={{ top: 8, right: 12, left: 8, bottom: 8 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--border)" /><XAxis type="number" domain={[0, 100]} tick={{ fill: "var(--muted-foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis dataKey="name" type="category" width={84} tick={{ fill: "var(--foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: "var(--accent)" }} contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} formatter={(value) => [`${value}%`, "الإنجاز"]} /><Bar dataKey="value" fill="var(--foreground)" radius={[0, 4, 4, 0]} barSize={14} /></BarChart></ResponsiveContainer></div></Card><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Market signals</p><h2>إشارات السوق</h2><span className="chart-note">{github ? `محدثة من GitHub: ${github.openIssues} issues و${github.openPullRequests} PRs` : "الإشارات والفرص التي اكتشفها المسح اليومي"}</span></div><div className="chart-legend"><span><i className="legend-line solid" /> إشارات</span><span><i className="legend-line dashed" /> فرص</span></div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={marketData} margin={{ top: 8, right: 8, left: -12, bottom: 4 }}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" /><XAxis dataKey="day" tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} width={24} /><Tooltip contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} /><Line type="monotone" dataKey="signals" stroke="var(--foreground)" strokeWidth={2} dot={{ r: 3, fill: "var(--foreground)" }} activeDot={{ r: 5 }} name="إشارات" /><Line type="monotone" dataKey="opportunities" stroke="var(--muted-foreground)" strokeWidth={2} strokeDasharray="5 5" dot={{ r: 3, fill: "var(--background)", stroke: "var(--foreground)" }} name="فرص" /></LineChart></ResponsiveContainer></div></Card></section>; }

function Overview({ go }: { go: (key: PageKey) => void }) {
  return <>
    <div className="page-heading"><div><p className="eyebrow">{pageMeta.overview.eyebrow}</p><h1>{pageMeta.overview.title}</h1><p className="page-description">{pageMeta.overview.description}</p></div><button className="primary-button" onClick={() => go("discovery")}><Radar size={16} /> افتح تقرير اليوم <ArrowUpRight size={15} /></button></div>
    <div className="stats-grid"><StatCard icon={Lightbulb} label="أفكار تحتاج قرارًا" value="04" note="+2 منذ آخر مراجعة" accent="amber" /><StatCard icon={Layers3} label="مشاريع قيد الحركة" value="03" note="واحد قريب من الإطلاق" accent="blue" /><StatCard icon={TrendingUp} label="إشارات جديدة" value="12" note="من مسح اليوم" accent="green" /><StatCard icon={TimerReset} label="وقت تم توفيره" value="6.4h" note="هذا الأسبوع" accent="violet" /></div>
    <div className="dashboard-grid">
      <section className="panel discovery-panel"><div className="signal-rule" /><div className="report-stamp"><span>تقرير بحثي شخصي</span><b>V.06 · 19 AUG 2026</b></div><div className="panel-head"><div><p className="eyebrow">Daily Discovery · 08:00</p><h2>تقرير الاكتشاف اليومي</h2></div><button className="ghost-button" onClick={() => go("discovery")}>عرض التقرير <ArrowUpRight size={14} /></button></div><div className="discovery-feature"><div className="discovery-art"><img src="/manus-storage/daily-discovery-illustration_d91bd052.png" alt="رسم توضيحي للاكتشاف اليومي" /></div><div className="feature-copy"><Pill tone="amber">فرصة قوية · 86/100</Pill><h3>أداة موبايل تساعد صناع المحتوى على إعادة تدوير أفكارهم إلى سلسلة منشورات.</h3><p>إشارة متكررة في مجتمعات المبدعين، مع فجوة واضحة في تجربة الهاتف وسرعة تحويل الملاحظة إلى خطة محتوى.</p><div className="source-row"><span><Globe2 size={13} /> 8 مصادر</span><span><Target size={13} /> 3 منافسين</span><span><Clock3 size={13} /> تحقق أولي: 2 يوم</span></div><div className="feature-actions"><button className="primary-button small" onClick={() => toast("تم حفظ نسخة جديدة للفكرة") }><Plus size={14} /> احفظ كفكرة</button><button className="outline-button small" onClick={() => toast("تم فتح مصادر التقرير التجريبية") }><ExternalLink size={14} /> المصادر</button></div></div></div></section>
      <section className="panel next-panel"><div className="panel-head"><div><p className="eyebrow">Focus</p><h2>ماذا الآن؟</h2></div><button className="icon-button"><MoreHorizontal size={17} /></button></div><div className="focus-item active"><div className="focus-marker"><Zap size={15} /></div><div><strong>اختبر افتراض الجمهور</strong><p>اسأل 5 صناع محتوى عن سير العمل الحالي.</p><span>20 دقيقة · اليوم</span></div></div><div className="focus-item"><div className="focus-marker muted"><GitBranch size={15} /></div><div><strong>راجع نسخة Habit Loop</strong><p>التقرير الأسبوعي ينتظر قرارك.</p><span>45 دقيقة · غدًا</span></div></div><div className="focus-item"><div className="focus-marker muted"><FileText size={15} /></div><div><strong>حوّل الإشارة إلى PRD</strong><p>الفرصة الجديدة جاهزة للتوثيق.</p><span>30 دقيقة · الخميس</span></div></div><button className="full-ghost" onClick={() => go("projects")}>عرض كل الأولويات <ArrowUpRight size={14} /></button></section>
    </div>
    <ProductToolsStrip go={go} />
    <ProjectHealthWidget go={go} />
    <DashboardCharts />
    <div className="lower-grid"><section className="panel activity-panel"><div className="panel-head"><div><p className="eyebrow">Activity</p><h2>آخر ما تحرك</h2></div><button className="ghost-button" onClick={() => go("knowledge")}>كل السجل <ArrowUpRight size={14} /></button></div><div className="timeline"><div className="timeline-item"><div className="timeline-icon amber"><Sparkles size={15} /></div><div><strong>تم إنشاء نسخة جديدة من «تطبيق المصروفات»</strong><p>بناءً على 6 إشارات سوقية جديدة</p></div><time>منذ 3 س</time></div><div className="timeline-item"><div className="timeline-icon blue"><Bot size={15} /></div><div><strong>اكتملت مهمة «مراقبة منافسي الإنتاجية»</strong><p>تقرير من 14 مصدرًا · 3 منافسين جدد</p></div><time>أمس</time></div><div className="timeline-item"><div className="timeline-icon green"><Check size={15} /></div><div><strong>تم تحديث حالة Habit Loop</strong><p>من «تطوير» إلى «اختبار مغلق»</p></div><time>أمس</time></div></div></section><section className="panel projects-mini"><div className="panel-head"><div><p className="eyebrow">Projects</p><h2>مشاريعك الآن</h2></div><button className="icon-button" onClick={() => go("projects")}><ArrowUpRight size={16} /></button></div><ProjectRow icon={Gamepad2} title="Pocket Quest" meta="لعبة · اختبار مغلق" progress={72} tone="amber" /><ProjectRow icon={Target} title="Habit Loop" meta="تطبيق · تطوير" progress={48} tone="blue" /><ProjectRow icon={MessageCircle} title="Talkback AI" meta="تطبيق · فكرة" progress={14} tone="violet" /></section></div>
  </>;
}

function ProjectRow({ icon: Icon, title, meta, progress, tone }: { icon: typeof Gamepad2; title: string; meta: string; progress: number; tone: string }) { return <div className="project-row"><div className={`project-icon ${tone}`}><Icon size={17} /></div><div className="project-info"><strong>{title}</strong><span>{meta}</span></div><div className="project-progress"><div className="progress-track"><i style={{ width: `${progress}%` }} /></div><span>{progress}%</span></div></div>; }

function Tasks({ tasks, setTasks }: { tasks: Task[]; setTasks: React.Dispatch<React.SetStateAction<Task[]>> }) {
  const [open, setOpen] = useState(false);
  const [draftName, setDraftName] = useState("");
  const [query, setQuery] = useState("");
  const toggleTask = (id: number) => setTasks((items) => items.map((task) => task.id === id ? { ...task, status: task.status === "نشطة" ? "متوقفة" : "نشطة" } : task));
  const addTask = () => { if (!draftName.trim()) return; setTasks((items) => [...items, { id: Date.now(), name: draftName, desc: "مهمة جديدة — إعداد تجريبي", cadence: "يوميًا · 10:00", status: "نشطة", last: "لم تعمل بعد", next: "غدًا، 10:00", icon: Bot, tone: "blue" }]); setDraftName(""); setOpen(false); toast("تمت إضافة المهمة التجريبية"); };
  return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.tasks.eyebrow}</p><h1>{pageMeta.tasks.title}</h1><p className="page-description">{pageMeta.tasks.description}</p></div><div className="page-actions"><button className="outline-button small" onClick={() => downloadCsv("ai-tasks.csv", ["المهمة", "الوصف", "التكرار", "الحالة", "آخر تشغيل", "التشغيل التالي"], tasks.map((task) => [task.name, task.desc, task.cadence, task.status, task.last, task.next]))}><FileText size={14} /> CSV</button><button className="outline-button small" onClick={() => printPdf("تصدير مهام الذكاء الاصطناعي", ["المهمة", "الوصف", "التكرار", "الحالة", "آخر تشغيل", "التشغيل التالي"], tasks.map((task) => [task.name, task.desc, task.cadence, task.status, task.last, task.next]))}><ExternalLink size={14} /> PDF</button><button className="primary-button" onClick={() => setOpen(true)}><Plus size={16} /> مهمة جديدة</button></div></div><div className="task-summary"><div><span>المهام النشطة</span><strong>{tasks.filter((t) => t.status === "نشطة").length}</strong></div><div><span>اكتملت اليوم</span><strong>02</strong></div><div><span>الوقت القادم</span><strong>غدًا 08:00</strong></div><div className="task-summary-note"><Sparkles size={16} /><span>كل نتيجة تحفظ كسجل مستقل ولا تستبدل القديم.</span></div></div><section className="panel tasks-panel"><div className="table-toolbar"><div className="toolbar-title"><h2>كل المهام</h2><span>{tasks.length} مهام</span></div><div className="toolbar-actions"><label className="inline-search"><Search size={14} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحث في المهام" /></label><button className="outline-button small"><Filter size={14} /> تصفية</button><button className="outline-button small"><Archive size={14} /> المؤرشفة</button></div></div><div className="task-table">{tasks.filter((task) => task.name.includes(query) || task.desc.includes(query)).map((task) => <div className="task-row" key={task.id}><div className={`task-icon ${task.tone}`}><task.icon size={17} /></div><div className="task-main"><strong>{task.name}</strong><span>{task.desc}</span></div><div className="task-cadence"><CalendarClock size={14} /><span>{task.cadence}</span></div><div className="task-run"><span>آخر تشغيل</span><strong>{task.last}</strong></div><div className="task-next"><span>التالي</span><strong>{task.next}</strong></div><div><Pill tone={task.status === "نشطة" ? "green" : "slate"}>{task.status}</Pill></div><div className="row-actions"><button className="icon-button" onClick={() => toggleTask(task.id)} title="إيقاف أو استئناف"><TimerReset size={16} /></button><button className="icon-button" onClick={() => toast("تم تشغيل المهمة تجريبيًا") } title="تشغيل الآن"><PlayIcon /></button><button className="icon-button" onClick={() => setTasks((items) => items.filter((item) => item.id !== task.id))} title="حذف"><X size={16} /></button></div></div>)}</div></section>{open && <div className="modal-backdrop" onClick={() => setOpen(false)}><div className="modal-card" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">New AI Task</p><h2>أنشئ مهمة جديدة</h2></div><button className="icon-button" onClick={() => setOpen(false)}><X size={18} /></button></div><label>اسم المهمة<input value={draftName} onChange={(e) => setDraftName(e.target.value)} placeholder="مثال: راقب ألعاب الأطفال التعليمية" autoFocus /></label><label>التعليمات الأولية<textarea placeholder="ما الذي تريد من المساعد أن يبحث عنه أو يفعله؟" /></label><div className="modal-grid"><label>التكرار<select defaultValue="daily"><option value="daily">يوميًا</option><option value="weekly">أسبوعيًا</option><option value="manual">يدويًا فقط</option></select></label><label>وقت التشغيل<select defaultValue="10"><option value="08">08:00</option><option value="10">10:00</option><option value="18">18:00</option></select></label></div><div className="modal-footer"><button className="outline-button" onClick={() => setOpen(false)}>إلغاء</button><button className="primary-button" onClick={addTask}><Check size={15} /> حفظ المهمة</button></div></div></div>}</>;
}

function PlayIcon() { return <span className="play-icon">▶</span>; }

function Discovery() { const signals = [{ score: 86, title: "مساعد إعادة تدوير أفكار المحتوى", type: "تطبيق · فرصة جديدة", sources: "8 مصادر", tone: "amber" }, { score: 78, title: "لعبة عادات قصيرة للجلسات اليومية", type: "لعبة · تطوير محتمل", sources: "11 مصدرًا", tone: "blue" }, { score: 72, title: "أداة متابعة تحديات المطورين المستقلين", type: "تطبيق · إشارة مبكرة", sources: "5 مصادر", tone: "violet" }]; return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.discovery.eyebrow}</p><h1>{pageMeta.discovery.title}</h1><p className="page-description">{pageMeta.discovery.description}</p></div><button className="outline-button" onClick={() => toast("سيتم تشغيل مسح جديد عند تفعيل التكامل") }><RefreshIcon /> شغّل مسحًا جديدًا</button></div><div className="discovery-banner"><div className="banner-signal-rule" /><div><Pill tone="green">اكتمل بنجاح</Pill><p className="briefing-label">MARKET BRIEF · 08:00</p><h2>تم تحليل 42 إشارة من السوق هذا الصباح.</h2><p>تمت إضافة 3 فرص جديدة، وتحديث 4 أفكار محفوظة، ورصد منافسين اثنين.</p></div><div className="radar-visual"><div className="radar-ring r1" /><div className="radar-ring r2" /><div className="radar-core"><Radar size={24} /></div><i /><i /><i /></div></div><div className="section-title-row"><div><p className="eyebrow">Opportunity feed</p><h2>الفرص الأعلى اليوم</h2></div><button className="ghost-button"><Filter size={14} /> كل الفلاتر</button></div><div className="opportunity-grid">{signals.map((signal) => <div className="opportunity-card" key={signal.title}><div className="opp-top"><Pill tone={signal.tone}>{signal.type}</Pill><span className={`score ${signal.tone}`}>{signal.score}</span></div><h3>{signal.title}</h3><p>تتقاطع مع مهاراتك في بناء تطبيقات الموبايل، ويمكن اختبارها بنموذج أولي واضح قبل التوسع.</p><div className="opp-meta"><span><Link2 size={13} /> {signal.sources}</span><span><Clock3 size={13} /> تحقق خلال 2 يوم</span></div><div className="opp-bottom"><button className="outline-button small" onClick={() => toast("تم فتح تفاصيل الفرصة التجريبية")}>التفاصيل</button><button className="icon-button"><MoreHorizontal size={16} /></button></div></div>)}</div></> }
function RefreshIcon() { return <span className="refresh-icon">↻</span>; }

const ideaExportRows = [["مساعد إعادة تدوير أفكار المحتوى", "فرصة جديدة", "86", "V3", "تحتاج اختبار"], ["Pocket Quest — موسم المهام اليومية", "تطوير مشروع", "81", "V7", "قيد التنفيذ"], ["مدير مصروفات للمستقلين", "فكرة محفوظة", "69", "V1", "مؤجلة"]];
function Ideas() { return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.ideas.eyebrow}</p><h1>{pageMeta.ideas.title}</h1><p className="page-description">{pageMeta.ideas.description}</p></div><div className="page-actions"><button className="outline-button small" onClick={() => downloadCsv("ideas.csv", ["الفكرة", "النوع", "النتيجة", "الإصدار", "الحالة"], ideaExportRows)}><FileText size={14} /> CSV</button><button className="outline-button small" onClick={() => printPdf("تصدير الأفكار", ["الفكرة", "النوع", "النتيجة", "الإصدار", "الحالة"], ideaExportRows)}><ExternalLink size={14} /> PDF</button><button className="primary-button" onClick={() => toast("سيتم فتح مولد الأفكار عند تفعيل الذكاء الاصطناعي") }><Sparkles size={16} /> ولّد فكرة</button></div></div><div className="idea-tabs"><button className="active">كل الأفكار <span>17</span></button><button>تحتاج قرارًا <span>4</span></button><button>مؤجلة <span>6</span></button><button>تم اختبارها <span>7</span></button></div><section className="idea-list panel">{[{ title: "مساعد إعادة تدوير أفكار المحتوى", tag: "فرصة جديدة", score: "86", version: "V3", status: "تحتاج اختبار", tone: "amber" }, { title: "Pocket Quest — موسم المهام اليومية", tag: "تطوير مشروع", score: "81", version: "V7", status: "قيد التنفيذ", tone: "blue" }, { title: "مدير مصروفات للمستقلين", tag: "فكرة محفوظة", score: "69", version: "V1", status: "مؤجلة", tone: "slate" }].map((idea) => <div className="idea-row" key={idea.title}><div className={`idea-bullet ${idea.tone}`}><Lightbulb size={17} /></div><div className="idea-body"><div className="idea-title"><h3>{idea.title}</h3><Pill tone={idea.tone}>{idea.tag}</Pill></div><p>نسخة {idea.version} · آخر تحديث من مهمة الاكتشاف اليومية · لديها فرضية تحتاج تحققًا.</p></div><div className="idea-score"><strong>{idea.score}</strong><span>ملاءمة</span></div><div className="idea-status"><span>{idea.status}</span><div className="mini-track"><i style={{ width: `${Number(idea.score) - 10}%` }} /></div></div><button className="icon-button"><ArrowUpRight size={16} /></button></div>)}</section></> }

function Projects() { return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.projects.eyebrow}</p><h1>{pageMeta.projects.title}</h1><p className="page-description">{pageMeta.projects.description}</p></div><button className="primary-button" onClick={() => toast("إنشاء مشروع جديد — نموذج تجريبي") }><Plus size={16} /> مشروع جديد</button></div><div className="project-board">{[{ title: "Pocket Quest", type: "لعبة موبايل", status: "اختبار مغلق", tone: "amber", progress: 72, icon: Gamepad2, next: "تحليل جلسات اللاعب" }, { title: "Habit Loop", type: "تطبيق إنتاجية", status: "تطوير", tone: "blue", progress: 48, icon: Target, next: "إنهاء نظام التذكيرات" }, { title: "Talkback AI", type: "تطبيق اجتماعي", status: "فكرة", tone: "violet", progress: 14, icon: MessageCircle, next: "اختبار المشكلة" }, { title: "Pocket Ledger", type: "أداة مالية", status: "متوقف مؤقتًا", tone: "slate", progress: 31, icon: Database, next: "مراجعة فرضية العميل" }].map((project) => <div className="project-card" key={project.title}><div className="project-card-top"><div className={`large-project-icon ${project.tone}`}><project.icon size={20} /></div><button className="icon-button"><MoreHorizontal size={16} /></button></div><Pill tone={project.tone}>{project.status}</Pill><h3>{project.title}</h3><p>{project.type}</p><div className="project-card-progress"><div className="progress-track"><i style={{ width: `${project.progress}%` }} /></div><span>{project.progress}%</span></div><div className="project-next"><span>الخطوة التالية</span><strong>{project.next}</strong></div></div>)}</div></> }

function SettingsPage({ userName, setUserName, password, setPassword, logout }: { userName: string; setUserName: (value: string) => void; password: string; setPassword: (value: string) => void; logout: () => void }) { const [nameDraft, setNameDraft] = useState(userName); const [passwordDraft, setPasswordDraft] = useState(password); const [provider, setProvider] = useState("Custom API"); const [endpoint, setEndpoint] = useState("https://api.example.com/v1"); const [apiKey, setApiKey] = useState(""); const [models, setModels] = useState<string[]>(["venture-reasoner", "venture-creative", "venture-fast"]); const [selectedModel, setSelectedModel] = useState("venture-reasoner"); const [fetchingModels, setFetchingModels] = useState(false); const [apiState, setApiState] = useState("لم يتم الاختبار"); const fetchModels = () => { setFetchingModels(true); setApiState("جارٍ جلب النماذج..."); setTimeout(() => { setModels(["venture-reasoner", "venture-creative", "venture-fast", "venture-vision"]); setSelectedModel("venture-reasoner"); setFetchingModels(false); setApiState("تم جلب 4 نماذج تجريبية"); toast("تم تحديث قائمة النماذج تجريبيًا"); }, 700); }; return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.settings.eyebrow}</p><h1>{pageMeta.settings.title}</h1><p className="page-description">{pageMeta.settings.description}</p></div><button className="outline-button" onClick={logout}><UserRound size={15} /> تسجيل الخروج</button></div><div className="settings-grid"><section className="panel settings-card"><div className="panel-head"><div><p className="eyebrow">Profile</p><h2>بيانات المستخدم</h2></div><div className="settings-icon"><UserRound size={18} /></div></div><label>اسم المستخدم<input value={nameDraft} onChange={(e) => setNameDraft(e.target.value)} /></label><label>وصف قصير<textarea defaultValue="مطور تطبيقات وألعاب موبايل" /></label><button className="primary-button small" onClick={() => { setUserName(nameDraft); toast("تم حفظ بيانات المستخدم تجريبيًا") }}><Check size={14} /> حفظ البيانات</button></section><section className="panel settings-card"><div className="panel-head"><div><p className="eyebrow">Security</p><h2>كلمة المرور</h2></div><div className="settings-icon"><Settings2 size={18} /></div></div><p className="settings-note">الدخول في هذا الـ Prototype يعتمد على كلمة مرور فقط. في النسخة الحقيقية سيتم حفظها بشكل آمن داخل Backend.</p><label>كلمة المرور الجديدة<input type="password" value={passwordDraft} onChange={(e) => setPasswordDraft(e.target.value)} /></label><button className="primary-button small" onClick={() => { setPassword(passwordDraft); toast("تم تغيير كلمة المرور تجريبيًا") }}><Check size={14} /> تحديث كلمة المرور</button></section><section className="panel settings-card api-settings-card"><div className="panel-head"><div><p className="eyebrow">AI Provider</p><h2>Custom API للذكاء الاصطناعي</h2></div><div className="settings-icon"><Bot size={18} /></div></div><label>اسم المزود<input value={provider} onChange={(e) => setProvider(e.target.value)} placeholder="OpenAI-compatible API" /></label><label>API Endpoint<input value={endpoint} onChange={(e) => setEndpoint(e.target.value)} placeholder="https://.../v1" /></label><label>API Key<input type="password" value={apiKey} onChange={(e) => setApiKey(e.target.value)} placeholder="••••••••••••" /></label><div className="api-actions"><button className="outline-button small" onClick={fetchModels} disabled={fetchingModels}>{fetchingModels ? <><Loader2 size={14} className="spin" /> جارٍ الجلب</> : <><RefreshIcon /> جلب النماذج</>}</button><span className="api-state">{apiState}</span></div><label>النموذج المستخدم<select value={selectedModel} onChange={(e) => setSelectedModel(e.target.value)}>{models.map((model) => <option value={model} key={model}>{model}</option>)}</select></label><button className="primary-button small" onClick={() => toast(`تم حفظ إعدادات ${provider} والنموذج ${selectedModel} تجريبيًا`)}><Check size={14} /> حفظ إعدادات الذكاء الاصطناعي</button></section><section className="panel settings-card provider-connect-card"><div className="panel-head"><div><p className="eyebrow">Provider connection</p><h2>ChatGPT / Codex</h2></div><div className="settings-icon"><Bot size={18} /></div></div><div className="provider-status-row"><span className="status-dot muted" /><strong>غير متصل</strong><span className="provider-badge">OAuth</span></div><p className="settings-note">تسجيل ChatGPT/Codex العام عبر OAuth ليس متاحًا كاعتماد API عام في هذا التطبيق حاليًا. لا نطلب كلمة مرور ChatGPT أو نخزن Token غير موثق. عند توفر Client رسمي معتمد يمكن تفعيل الربط الآمن هنا.</p><button className="outline-button small" onClick={() => toast("سيتم تفعيل OAuth بعد توفير تسجيل تطبيق رسمي من المزود") }><Link2 size={14} /> ربط ChatGPT / Codex</button></section></div></> }

function GithubSettingsCard() {
  const settingsQuery = trpc.github.getSettings.useQuery();
  const save = trpc.github.saveSettings.useMutation({ onSuccess: () => { settingsQuery.refetch(); toast("تم حفظ إعدادات GitHub بأمان"); }, onError: (error) => toast(`تعذر حفظ GitHub: ${error.message}`) });
  const deleteConnection = trpc.github.deleteSettings.useMutation({ onSuccess: () => { settingsQuery.refetch(); toast("تم حذف اتصال GitHub"); } });
  const statusQuery = trpc.github.status.useQuery(undefined, { enabled: Boolean(settingsQuery.data?.connected) });
  const [token, setToken] = useState("");
  const [repoOwner, setRepoOwner] = useState("");
  const [repoName, setRepoName] = useState("");
  useEffect(() => { if (settingsQuery.data) { setRepoOwner(settingsQuery.data.repoOwner); setRepoName(settingsQuery.data.repoName); } }, [settingsQuery.data]);
  const connected = settingsQuery.data?.connected;
  return <section className="panel settings-card github-settings-card"><div className="panel-head"><div><p className="eyebrow">Repository intelligence</p><h2>GitHub</h2></div><div className="settings-icon"><GitBranch size={18} /></div></div><p className="settings-note">أدخل Token بصلاحية قراءة فقط، وسيتم حفظه في Backend ولن يظهر كاملًا مرة أخرى في الواجهة.</p><label>GitHub Token<input type="password" value={token} onChange={(e) => setToken(e.target.value)} placeholder={connected ? settingsQuery.data?.token ?? "محفوظ" : "ghp_..."} /></label><div className="github-repo-fields"><label>Owner<input value={repoOwner} onChange={(e) => setRepoOwner(e.target.value)} placeholder="username أو organization" /></label><label>Repository<input value={repoName} onChange={(e) => setRepoName(e.target.value)} placeholder="repository-name" /></label></div><div className="api-actions"><button className="primary-button small" disabled={save.isPending || !repoOwner || !repoName || (!token && !connected)} onClick={() => save.mutate({ token: token || undefined, repoOwner, repoName })}>{save.isPending ? <><Loader2 size={14} className="spin" /> جارٍ الحفظ</> : <><Check size={14} /> حفظ الاتصال</>}</button>{connected && <button className="outline-button small" disabled={deleteConnection.isPending} onClick={() => deleteConnection.mutate()}><X size={14} /> حذف الاتصال</button>}</div>{connected && <div className="github-health-inline">{statusQuery.isLoading ? <><Loader2 size={14} className="spin" /> جارٍ قراءة حالة المستودع</> : statusQuery.data?.connected ? <><CheckCircle2 size={14} /> {statusQuery.data.repo} · صحة {statusQuery.data.health}% · {statusQuery.data.recentCommits} commits حديثة</> : <><AlertTriangle size={14} /> تعذر قراءة المستودع</>}</div>}</section>;
}

function ProductToolsStrip({ go }: { go: (key: PageKey) => void }) { const tools = [{ key: "validation" as PageKey, icon: ClipboardCheck, title: "Validation Lab", desc: "اختبر الفكرة قبل البناء" }, { key: "briefs" as PageKey, icon: FileCode2, title: "Product Brief", desc: "جهّز ملف Claude Code" }, { key: "health" as PageKey, icon: HeartPulse, title: "Project Health", desc: "اعرف أين تتدخل الآن" }]; return <section className="product-tools-strip">{tools.map((tool) => <button key={tool.key} className="product-tool-card" onClick={() => go(tool.key)}><span className="tool-card-icon"><tool.icon size={18} /></span><span><strong>{tool.title}</strong><small>{tool.desc}</small></span><ArrowUpRight size={15} /></button>)}</section>; }

function ValidationLab() { const [idea, setIdea] = useState(""); const [experiment, setExperiment] = useState("landing"); const [created, setCreated] = useState(false); const [successMetric, setSuccessMetric] = useState("10 تسجيلات مهتمة"); return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.validation.eyebrow}</p><h1>{pageMeta.validation.title}</h1><p className="page-description">{pageMeta.validation.description}</p></div><button className="primary-button" onClick={() => { setCreated(true); toast("تم إنشاء تجربة التحقق"); }}><Plus size={16} /> تجربة جديدة</button></div><div className="validation-grid"><section className="panel tool-form-card"><div className="panel-head"><div><p className="eyebrow">Step 01</p><h2>عرّف الفرضية</h2></div><ClipboardCheck size={20} /></div><label>الفكرة التي تريد اختبارها<textarea value={idea} onChange={(e) => setIdea(e.target.value)} placeholder="مثال: تطبيق يساعد المستقلين على متابعة المصروفات..." /></label><label>نوع التجربة<select value={experiment} onChange={(e) => setExperiment(e.target.value)}><option value="landing">صفحة هبوط</option><option value="survey">استبيان قصير</option><option value="prototype">Prototype تفاعلي</option><option value="ad">إعلان تجريبي</option></select></label><label>معيار النجاح<input value={successMetric} onChange={(e) => setSuccessMetric(e.target.value)} /></label><button className="primary-button" onClick={() => { setCreated(true); toast("تم حفظ خطة التجربة"); }}><CheckCircle2 size={15} /> احفظ خطة التحقق</button></section><section className="panel validation-result-card"><div className="panel-head"><div><p className="eyebrow">Step 02</p><h2>قرار قابل للقياس</h2></div><Target size={20} /></div>{created ? <div className="validation-created"><CheckCircle2 size={34} /><h3>التجربة جاهزة للتنفيذ</h3><p>{idea || "فكرتك الجديدة"} · {experiment === "landing" ? "صفحة هبوط" : experiment} · الهدف: {successMetric}</p><div className="decision-row"><span>المدة المقترحة</span><strong>48 ساعة</strong></div><div className="decision-row"><span>القرار بعد التجربة</span><strong>استمر إذا تحقق المعيار</strong></div><button className="outline-button" onClick={() => toast("تم تصدير خطة التحقق") }><Download size={14} /> تصدير الخطة</button></div> : <div className="empty-state"><ClipboardCheck size={30} /><h3>ابدأ بفكرة واحدة</h3><p>سيساعدك المختبر على تحويلها إلى فرضية وتجربة ومعيار نجاح.</p></div>}</section></div></>; }

function ProductBrief() {
  const [idea, setIdea] = useState("مساعد إعادة تدوير أفكار المحتوى");
  const [productType, setProductType] = useState("تطبيق موبايل");
  const [focus, setFocus] = useState("ابنِ نسخة أولى صغيرة، واضحة، قابلة للقياس، مع اختبارات أساسية.");
  const [brief, setBrief] = useState<null | { problem: string; targetUser: string; valueProposition: string; scope: string[]; screens: string[]; userStories: string[]; dataModel: string[]; acceptanceCriteria: string[]; risks: string[]; nextStep: string }>(null);
  const generateBrief = trpc.productBrief.generate.useMutation({ onSuccess: (data) => { setBrief(data); toast("تم توليد Product Brief من نموذج الذكاء الاصطناعي"); }, onError: (error) => toast(`تعذر توليد الوثيقة: ${error.message}`) });
  const briefRows = brief ? [["الفكرة", idea], ["المشكلة", brief.problem], ["المستخدم", brief.targetUser], ["القيمة", brief.valueProposition], ["النطاق", brief.scope.join(" • ")], ["الشاشات", brief.screens.join(" • ")], ["User Stories", brief.userStories.join(" • ")], ["Data Model", brief.dataModel.join(" • ")], ["Acceptance Criteria", brief.acceptanceCriteria.join(" • ")], ["المخاطر", brief.risks.join(" • ")], ["الخطوة التالية", brief.nextStep]] : [];
  const context = brief ? `# ${idea}

## Problem
${brief.problem}

## Target User
${brief.targetUser}

## Value Proposition
${brief.valueProposition}

## Scope
${brief.scope.map((x) => `- ${x}`).join("\n")}

## Screens
${brief.screens.map((x) => `- ${x}`).join("\n")}

## User Stories
${brief.userStories.map((x) => `- ${x}`).join("\n")}

## Data Model
${brief.dataModel.map((x) => `- ${x}`).join("\n")}

## Acceptance Criteria
${brief.acceptanceCriteria.map((x) => `- ${x}`).join("\n")}

## Risks
${brief.risks.map((x) => `- ${x}`).join("\n")}

## Next Step
${brief.nextStep}` : "";
  const run = () => generateBrief.mutate({ idea, productType, focus });
  return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.briefs.eyebrow}</p><h1>{pageMeta.briefs.title}</h1><p className="page-description">{pageMeta.briefs.description}</p></div><div className="page-actions"><button className="outline-button small" disabled={!brief} onClick={() => printPdf("Product Brief — Venture OS", ["القسم", "المحتوى"], briefRows)}><ExternalLink size={14} /> PDF</button><button className="primary-button" disabled={generateBrief.isPending} onClick={run}>{generateBrief.isPending ? <><Loader2 size={15} className="spin" /> جارٍ التحليل</> : <><Sparkles size={16} /> ولّد بالذكاء الاصطناعي</>}</button></div></div><div className="brief-layout"><section className="panel tool-form-card"><div className="panel-head"><div><p className="eyebrow">AI Input</p><h2>من الفكرة إلى المنتج</h2></div><FileCode2 size={20} /></div><label>اسم الفكرة<input value={idea} onChange={(e) => { setIdea(e.target.value); setBrief(null); }} /></label><label>نوع المنتج<select value={productType} onChange={(e) => { setProductType(e.target.value); setBrief(null); }}><option>تطبيق موبايل</option><option>لعبة موبايل</option><option>منتج رقمي</option></select></label><label>تركيز التحليل<textarea value={focus} onChange={(e) => { setFocus(e.target.value); setBrief(null); }} /></label><button className="primary-button" disabled={generateBrief.isPending} onClick={run}><FileCode2 size={15} /> إنشاء Product Brief فعلي</button><p className="settings-note">يتم استدعاء النموذج من الخادم حتى لا يظهر أي مفتاح API في المتصفح.</p></section><section className="panel brief-preview"><div className="brief-document-head"><span className="document-mark">V</span><div><strong>VENTURE OS / PRODUCT BRIEF</strong><small>{brief ? "مخرجات حقيقية من نموذج الذكاء الاصطناعي" : "بانتظار التحليل"}</small></div></div>{brief ? <div className="brief-document"><h2>{idea}</h2>{[["01", "المشكلة", brief.problem], ["02", "المستخدم والقيمة", `${brief.targetUser} — ${brief.valueProposition}`], ["03", "النطاق والشاشات", `${brief.scope.join(" • ")} — ${brief.screens.join(" • ")}`], ["04", "User Stories", brief.userStories.join(" • ")], ["05", "Data Model", brief.dataModel.join(" • ")], ["06", "Acceptance Criteria", brief.acceptanceCriteria.join(" • ")], ["07", "المخاطر والخطوة التالية", `${brief.risks.join(" • ")} — ${brief.nextStep}`]].map(([number, title, body]) => <div className="brief-section" key={number}><span>{number}</span><div><strong>{title}</strong><p>{body}</p></div></div>)}<div className="brief-actions"><button className="outline-button" onClick={() => { navigator.clipboard?.writeText(context); toast("تم نسخ Product Brief كاملًا"); }}><FileCode2 size={14} /> نسخ السياق لـ Claude Code</button><button className="outline-button" onClick={() => downloadCsv("product-brief.csv", ["القسم", "المحتوى"], briefRows)}><Download size={14} /> CSV</button></div></div> : <div className="empty-state"><FileCode2 size={30} /><h3>{generateBrief.isPending ? "النموذج يحلل الفكرة..." : "ابدأ بتحليل فعلي"}</h3><p>{generateBrief.isPending ? "نرتب المشكلة والنطاق والشاشات ومعايير القبول." : "اكتب الفكرة واضغط الزر للحصول على Product Brief ديناميكي."}</p></div>}</section></div></>;
}

function ProjectHealthWidget({ go }: { go: (key: PageKey) => void }) {
  const { isAuthenticated } = useAuth();
  const statusQuery = trpc.github.status.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const demoProjects = [{ name: "Pocket Quest", health: 82, next: "تحليل جلسات اللاعب" }, { name: "Habit Loop", health: 61, next: "إنهاء نظام التذكيرات" }, { name: "Talkback AI", health: 38, next: "اختبار المشكلة" }];
  const github = statusQuery.data?.connected ? { name: statusQuery.data.repo, health: statusQuery.data.health, next: `${statusQuery.data.recentCommits} commits حديثة · ${statusQuery.data.openIssues} issues مفتوحة` } : null;
  const projects = github ? [github, ...demoProjects.slice(0, 2)] : demoProjects;
  return <section className="panel health-widget"><div className="panel-head"><div><p className="eyebrow">Project Health Monitor</p><h2>صحة مشاريعك الآن</h2><span className="chart-note">{github ? "بيانات GitHub محدثة تلقائيًا" : "بيانات تجريبية — اربط GitHub من Settings"}</span></div><button className="ghost-button" onClick={() => go("health")}>التفاصيل <ArrowUpRight size={14} /></button></div><div className="health-widget-list">{projects.map((project) => <div className="health-widget-row" key={project.name}><div><strong>{project.name}</strong><span>{project.next}</span></div><div className="health-widget-meter"><i style={{ width: `${project.health}%` }} /></div><b>{project.health}%</b></div>)}</div>{statusQuery.isFetching && <div className="github-health-inline"><Loader2 size={13} className="spin" /> جارٍ تحديث بيانات GitHub</div>}</section>;
}

function ProjectHealth() { const projects = [{ name: "Pocket Quest", type: "لعبة", health: 82, trend: "صاعد", next: "تحليل جلسات اللاعب", tone: "green" }, { name: "Habit Loop", type: "تطبيق", health: 61, trend: "يحتاج انتباه", next: "إنهاء نظام التذكيرات", tone: "amber" }, { name: "Talkback AI", type: "تطبيق", health: 38, trend: "متوقف", next: "اختبار المشكلة", tone: "violet" }]; return <><div className="page-heading"><div><p className="eyebrow">{pageMeta.health.eyebrow}</p><h1>{pageMeta.health.title}</h1><p className="page-description">{pageMeta.health.description}</p></div><button className="outline-button" onClick={() => toast("تم تحديث مؤشرات المشاريع تجريبيًا")}><RefreshIcon /> تحديث المؤشرات</button></div><div className="health-summary"><StatCard icon={HeartPulse} label="متوسط صحة المشاريع" value="60%" note="من 3 مشاريع" accent="green" /><StatCard icon={AlertTriangle} label="تحتاج انتباهًا" value="01" note="قرار خلال 48 ساعة" accent="amber" /><StatCard icon={CheckCircle2} label="تجارب مكتملة" value="08" note="هذا الشهر" accent="blue" /></div><section className="health-grid">{projects.map((project) => <Card className="health-card" key={project.name}><div className="health-card-head"><div><p className="eyebrow">{project.type}</p><h2>{project.name}</h2></div><span className={`health-score ${project.tone}`}>{project.health}</span></div><div className="health-meter"><i style={{ width: `${project.health}%` }} /></div><div className="health-meta"><span>الاتجاه</span><strong>{project.trend}</strong></div><div className="health-next"><span>الخطوة التالية</span><strong>{project.next}</strong></div><button className="full-ghost" onClick={() => toast(`تم فتح لوحة ${project.name}`)}>فتح المشروع <ArrowUpRight size={14} /></button></Card>)}</section></>; }

function SimplePage({ page }: { page: PageKey }) { const meta = pageMeta[page]; const PageIcon = page === "telegram" ? MessageCircle : page === "competitors" ? Target : Database; return <><div className="page-heading"><div><p className="eyebrow">{meta.eyebrow}</p><h1>{meta.title}</h1><p className="page-description">{meta.description}</p></div><button className="outline-button" onClick={() => toast("هذه الشاشة تجريبية في الـ Prototype") }><Command size={15} /> إجراءات سريعة</button></div><div className="empty-hero panel"><div className="empty-icon"><PageIcon size={28} /></div><h2>{page === "telegram" ? "اربط Telegram عندما تكون جاهزًا" : page === "competitors" ? "خريطة المنافسين ستتسع مع كل مسح" : "معرفتك في مكان واحد"}</h2><p>هذه شاشة تمهيدية داخل الـ Prototype لتصور المكان النهائي. ستتصل بالبيانات الحقيقية عند بدء مرحلة التنفيذ.</p><button className="primary-button" onClick={() => toast("تم تسجيل اهتمامك بهذه الوحدة") }><Sparkles size={15} /> جرّب التفاعل</button></div></> }

function LoginScreen({ onLogin }: { onLogin: (password: string, remember: boolean) => boolean }) { const [value, setValue] = useState(""); const [remember, setRemember] = useState(false); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const submit = (event: React.FormEvent) => { event.preventDefault(); if (loading) return; setLoading(true); setTimeout(() => { const accepted = onLogin(value, remember); if (!accepted) { setError("كلمة المرور غير صحيحة"); setLoading(false); } }, 650); }; return <div className="login-screen" dir="rtl"><div className="login-orbit" /><div className="login-card"><div className="login-logo"><img src="/manus-storage/venture-os-mark_cc2bdbe7.png" alt="" /></div><p className="eyebrow">Personal AI Venture OS</p><h1>مساحتك تبدأ من هنا.</h1><p>أدخل كلمة المرور للوصول إلى مختبر الأفكار والمشاريع.</p><form onSubmit={submit}><label>كلمة المرور<input type="password" value={value} onChange={(e) => { setValue(e.target.value); setError(""); }} placeholder="••••••••" autoFocus disabled={loading} /></label><label className="remember-row"><input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} disabled={loading} /><span>تذكرني على هذا الجهاز</span></label>{error && <span className="login-error">{error}</span>}<button className="primary-button" type="submit" disabled={loading}>{loading ? <><Loader2 size={15} className="spin" /> جارٍ التحقق...</> : <><ArrowUpRight size={15} /> دخول إلى المساحة</>}</button></form><small>Prototype · كلمة المرور الافتراضية: 1234</small></div></div> }

export default function Home() {
  // The useAuth hook provides authentication state.
  // To implement login/logout, call logout(), or start login from an event
  // handler: onClick={() => startLogin()} (imported from "@/const"). Never call
  // startLogin() during render (no href={startLogin()}) — it mints a one-time
  // nonce cookie and must run only at the moment of navigation.
  let { user, loading, error, isAuthenticated, logout } = useAuth();

  const [active, setActive] = useState<PageKey>("overview");
  const [tasks, setTasks] = useState<Task[]>(initialTasks);
  const [authenticated, setAuthenticated] = useState(() => typeof window !== "undefined" && window.localStorage.getItem("venture-os-remembered") === "true");
  const [password, setPassword] = useState("1234");
  const [userName, setUserName] = useState("مطور مستقل");
  const content = useMemo(() => { if (active === "overview") return <Overview go={setActive} />; if (active === "tasks") return <Tasks tasks={tasks} setTasks={setTasks} />; if (active === "discovery") return <Discovery />; if (active === "ideas") return <Ideas />; if (active === "projects") return <Projects />; if (active === "settings") return <SettingsPage userName={userName} setUserName={setUserName} password={password} setPassword={setPassword} logout={() => { setAuthenticated(false); window.localStorage.removeItem("venture-os-remembered"); }} />; if (active === "validation") return <ValidationLab />; if (active === "briefs") return <ProductBrief />; if (active === "health") return <ProjectHealth />; return <SimplePage page={active} />; }, [active, tasks, password, userName]);
  if (!authenticated) return <LoginScreen onLogin={(value, remember) => { if (value === password) { setAuthenticated(true); if (remember) window.localStorage.setItem("venture-os-remembered", "true"); else window.localStorage.removeItem("venture-os-remembered"); return true; } return false; }} />;
  return <AppShell active={active} setActive={setActive} userName={userName} logout={() => { setAuthenticated(false); window.localStorage.removeItem("venture-os-remembered"); }}>{content}<footer className="prototype-footer"><span><CircleDot size={12} /> Prototype · بيانات تجريبية فقط</span><span>Personal AI Venture OS <span className="footer-divider">·</span> v0.2</span></footer></AppShell>;
}
